/// <summary>
/// Business event triggered when a BOM calculation is completed.
/// </summary>
[BusinessEvents(classStr(AAXBOMCalcCompletedBusinessEventContract), 'BOMCalcCompletedBusinessEventName', 'BOMCalcCompletedBusinessEventDescription', ModuleAxapta::Production)]
public final class AAXBOMCalcCompletedBusinessEvent extends BusinessEventsBase
{
    private BOMCalcTable bomCalcTable;

}

Method.Source:
/// <summary>
/// Gets or sets the source BOMCalcTable for building the event contract.
/// </summary>
private BOMCalcTable parmBOMCalcTable(BOMCalcTable _bomCalcTable = bomCalcTable)
{
    bomCalcTable = _bomCalcTable;

    return bomCalcTable;
}

/// <summary>
/// Creates a new <c>AAXBOMCalcCompletedBusinessEvent</c> instance from the specified <c>BOMCalcTable</c> record.
/// </summary>
/// <param name="_bomCalcTable">The source BOMCalcTable record.</param>
/// <returns>A new instance of <c>AAXBOMCalcCompletedBusinessEvent</c>.</returns>
public static AAXBOMCalcCompletedBusinessEvent newFromBOMCalcTable(BOMCalcTable _bomCalcTable)
{
    AAXBOMCalcCompletedBusinessEvent businessEvent = new AAXBOMCalcCompletedBusinessEvent();
    businessEvent.parmBOMCalcTable(_bomCalcTable);

    return businessEvent;
}

/// <summary>
/// Private constructor. Use static factory methods to create instances.
/// </summary>
private void new()
{
}

/// <summary>
/// Builds the data contract for this business event.
/// </summary>
/// <returns>The populated <c>AAXBOMCalcCompletedBusinessEventContract</c>.</returns>
[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    return AAXBOMCalcCompletedBusinessEventContract::newFromBOMCalcTable(bomCalcTable);
}
